import { Acl, Role } from '@servicenow/sdk/core'

const role_meta_first_install = Role({
    $meta: {
        installMethod: 'first install',
    },
    name: 'x_meta.role_meta_first_install',
})

Acl({
    $id: Now.ID['acl-id-meta-first-install'],
    $meta: {
        installMethod: 'first install',
    },
    operation: 'write',
    type: 'record',
    table: 'task',
    roles: [role_meta_first_install],
    condition: 'priority=2^active=true',
    field: 'description',
    appliesTo: 'active=true',
})
